class Solution {
    public int findMinArrowShots(int[][] points){
        Arrays.sort(points,(a,b)->Integer.compare(a[1],b[1]));
        int arrows=1;
        long position=points[0][1];
        for(int i=1;i<points.length;i++)if(points[i][0]>position){
            arrows++;
            position=points[i][1];
        }
        return arrows;
    }
}

code.kotlin:
class Solution {
    fun findMinArrowShots(points:Array<IntArray>):Int{
        points.sortWith(Comparator.comparingInt{
            it[1]
        });
        var arrows=1;
        var position=points[0][1].toLong();
        for(i in 1 until points.size)if(points[i][0]>position){
            arrows++;
            position=points[i][1].toLong()
        };
        return arrows
    }
}

code.cpp:
class Solution {
    public: int findMinArrowShots(vector<vector<int>>& points){
        sort(points.begin(),points.end(),[](const auto& a,const auto& b){
            return a[1]<b[1];
        });
        int arrows=1;
        long long position=points[0][1];
        for(int i=1;i<(int)points.size();++i)if(points[i][0]>position){
            ++arrows;
            position=points[i][1];
        }
        return arrows;
    }
};
